# 创建配置目录
sudo mkdir -p /etc/cni/net.d

# 创建 ptp 网络配置
echo '{
  "cniVersion": "0.4.0",
  "name": "myptp",
  "type": "ptp",
  "ipMasq": true,
  "ipam": {
    "type": "host-local",
    "subnet": "172.16.29.0/24",
    "routes": [
      { "dst": "0.0.0.0/0" }
    ]
  }
}' | sudo tee /etc/cni/net.d/10-myptp.conf
